import hlevels; import nat;
notation lexical { numeral(n : Nat) := n; }
use lexical;

theory T(U < UU0) { M : set U; c : M; op(n : Nat, x, y : M) : M;
  def helper0(x : M) : M := op(0,x,c);
  def wrapped(c : M, proof_ : c = c) : M := (fun (x : M) => helper0(x))(c);
  law same(c : M) : helper0(c) = op(0,c,c);
  def iter(n : Nat) : M := match n { zero => c; succ(k) => op(0,iter(k),c); };
def twice(n : Nat) : M := op(0,iter(n),c);
}
notation shifted { numeral(n : Nat) := succ(n); }
use shifted;
theory Child(U < UU0) extends T {
  def fresh(x : M) : M := op(0,x,c);
}
def intended(S : Child(U0), x : S.M) : S.wrapped(x,refl(x)) = S.op(zero,x,S.c) := refl(S.op(zero,x,S.c));
def named(S : Child(U0), x : S.M) : S.M := Child.wrapped(S,c := x,proof_ := refl(x));
def captured(S : Child(U0), x : S.M) : S.wrapped(x,refl(x)) = S.op(zero,x,x) := refl(S.op(zero,x,x));
def law_meaning(S : Child(U0), x : S.M) : S.op(zero,x,S.c) = S.op(zero,x,x) := S.same(x);
def identity(S : Child(U0), x : S.M) : Child.Hom.compose(Child.Hom.id(S),Child.Hom.id(S)).map(x) = x { rfl; }
def child_selection(S : Child(U0), x : S.M) : S.fresh(x) = S.op(succ(zero),x,S.c) { rfl; }
def earlier_call(S : Child(U0)) : S.twice(zero) = S.op(zero,S.c,S.c) { rfl; }
initial N : Child(U0);
def generated(x : N) : N.model.wrapped(x,refl(x)) = N.op(zero,x,N.c) { rfl; }
def forget(x : N) : Unit := match x { N.c => tt; _ => tt; };
def forgotten : forget(N.op(zero,N.c,N.c)) = tt { rfl; }
free W(A : U0) : Child(U0) on A;
def fold_computes(S : Child(U0), x : S.M) : W.fold(S.M,S,fun (a : S.M) => a).map(W.gen(x)) = x { rfl; }
def ordinary : U0 := forall unused : Unit. Unit;
inductive Boundary : set U0 { left_; right_; path_ : left_ = right_; }
def mismatch(x : Boundary) : Boundary := match x { left_ => left_; _ => right_; };

